def sum_above_threshold(values, threshold):
    """Return the sum of values greater than threshold."""
    total = 0
    for v in values:
        if v > threshold:
            total = total + v
    return total

def print_large_values(values, threshold):
    """Print each value above the threshold."""
    for v in values:
        if v > threshold:
            print('Large number:', v)

def print_even_numbers(values):
    """Print each even number in the list."""
    for v in values:
        if v % 2 == 0:
            print('Even number:', v)

def main():
    data = [10, 20, 30, 40, 50]
    print_large_values(data, 15)
    total = sum_above_threshold(data, 15)
    print('Sum of large numbers:', total)

    data2 = [1, 2, 3, 4, 5, 6]
    print_even_numbers(data2)

if __name__ == '__main__':
    main()

