def clean_text(text):
    cleaned = ''
    for c in text:
        if c.isalpha() or c.isspace():
            cleaned = cleaned + c.lower()
    return cleaned

def extract_long_words(cleaned):
    words = cleaned.split()
    long_words = []
    for w in words:
        if len(w) > 4:
            long_words.append(w)
    return long_words

def filter_by_prefix(words, prefixes):
    result = {}
    for w in words:
        for p in prefixes:
            if w.startswith(p):
                result[w] = len(w)
                break
    return result

def analyze(text):
    cleaned = clean_text(text)
    long_words = extract_long_words(cleaned)
    return filter_by_prefix(long_words, ['a', 'e'])

print(analyze('  Apple banana   ELEPHANT  '))

