def parse_line(line):
    parts = line.strip().split(',')
    if len(parts) != 3:
        raise ValueError('Invalid line format')
    region = parts[0]
    amount = float(parts[2])
    return region, amount

def accumulate_totals(lines):
    totals = {}
    for line in lines:
        region, amount = parse_line(line)
        totals[region] = totals.get(region, 0) + amount
    return totals

def read_file(path):
    with open(path, 'r') as f:
        return f.readlines()

def generate_report(totals):
    print('Sales Report')
    for region, total in totals.items():
        print(region + ': ' + str(total))

def main():
    lines = read_file('sales.txt')
    totals = accumulate_totals(lines)
    generate_report(totals)

if __name__ == '__main__':
    main()

