import json
from contextlib import contextmanager

@contextmanager
def managed_file(path):
    f = open(path, 'r')
    try:
        yield f
    finally:
        f.close()

def read_json(file_obj):
    raw = file_obj.read()
    return json.loads(raw)

def validate_item(item):
    if not isinstance(item, dict):
        raise ValueError('Item must be a dict')
    if 'id' not in item or 'value' not in item:
        raise ValueError('Missing required keys')
    if not isinstance(item['value'], (int, float)):
        raise ValueError('Value must be numeric')
    return True

def aggregate_values(items):
    total = 0
    for item in items:
        total = total + item['value']
    return total

def process_data(path):
    with managed_file(path) as f:
        try:
            items = read_json(f)
        except json.JSONDecodeError as e:
            raise RuntimeError('Invalid JSON') from e
    valid_items = [item for item in items if validate_item(item)]
    total = aggregate_values(valid_items)
    print('Total value:', total)
    return len(valid_items)

process_data('data.json')
